# ==================================================================================
# Analyzes Latency Metrics:
#   - Processing Latency: time taken to predict and schedule next chord
#   - Alignment Jitter: playback latency (how much we are deviating from the grid)
#
# Usage: python analyze_latency.py <log_file>
# Based on the log file generated by the pipeline
# ==================================================================================


import json
import argparse
import statistics
from pathlib import Path
import sys

def analyze_log(file_path):
    print(f"Loading metrics from: {file_path}")
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        print(f"Error loading file: {e}")
        return

    if not data:
        print("No data found in log file.")
        return

    processing_latencies = [d['processing_latency'] * 1000 for d in data] # Convert to ms
    alignment_jitters = [d['alignment_jitter'] * 1000 for d in data]     # Convert to ms

    print("\n" + "="*50)
    print("LATENCY & JITTER ANALYSIS")
    print("="*50)
    print(f"Total Samples: {len(data)}")
    
    # Processing Latency Analysis
    if processing_latencies:
        avg_lat = statistics.mean(processing_latencies)
        std_lat = statistics.stdev(processing_latencies) if len(processing_latencies) > 1 else 0.0
        max_lat = max(processing_latencies)
        min_lat = min(processing_latencies)
        
        print("\n--- Processing Latency ---")
        print(f"Average:   {avg_lat:.2f} ms")
        print(f"Std Dev:   {std_lat:.2f} ms")
        print(f"Min:       {min_lat:.2f} ms")
        print(f"Max:       {max_lat:.2f} ms")

    # Alignment Jitter Analysis
    if alignment_jitters:
        avg_jit = statistics.mean(alignment_jitters)
        std_jit = statistics.stdev(alignment_jitters) if len(alignment_jitters) > 1 else 0.0
        max_jit = max(alignment_jitters)
        min_jit = min(alignment_jitters)
        
        print("\n--- Alignment Jitter (Grid Deviation) ---")
        print(f"Average:   {avg_jit:.2f} ms")
        print(f"Std Dev:   {std_jit:.2f} ms")
        print(f"Min:       {min_jit:.2f} ms")
        print(f"Max:       {max_jit:.2f} ms")
        
    print("\n" + "="*50)
    

def main():
    parser = argparse.ArgumentParser(description="Analyze Latency Metrics")
    parser.add_argument("file", nargs="?", help="Path to JSON log file. If omitted, uses latest in logs/")
    args = parser.parse_args()
    
    file_path = args.file
    
    if not file_path:
        # Find latest log file
        logs_dir = Path("logs")
        if not logs_dir.exists():
            print("No logs directory found.")
            return
            
        json_files = list(logs_dir.glob("latency_metrics_*.json"))
        if not json_files:
            print("No latency metrics files found in logs/.")
            return
            
        # Get latest file
        file_path = max(json_files, key=lambda p: p.stat().st_mtime)
        
    analyze_log(file_path)

if __name__ == "__main__":
    main()
